// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(amount > 0);
        vm.assume(caller != address(0));
        vm.deal(caller, amount);
        vm.prank(caller);
        (bool ok,) = address(c).call{value: amount}("");
        require(ok, "deposit failed");
        uint256 balanceBefore = c.balances(caller);
        uint256 ethBefore = address(c).balance;
        vm.prank(caller);
        c.withdraw();
        uint256 balanceAfter = c.balances(caller);
        uint256 ethAfter = address(c).balance;
        assertTrue(balanceAfter != 0 || (ethBefore - ethAfter) == balanceBefore);
    }
}
